 78	
 79	public class ValidationService {
 80	
 81	    private final ProductService productService;
 82	
 83	    public ValidationService(ProductService productService) {
 84	        this.productService = productService;
 85	    }
 86	
 87	    public void validateCheckout(CheckoutRequestDto request) {
 88	        validateItems(request);
 89	        validateCustomer(request);
 90	        validateRegion(request);
 91	        validateZipCode(request);
 92	        validateShippingMethod(request);
 93	        validateClubTier(request);
 94	        validateCoupon(request);
 95	        validatePaymentMethod(request);
 96	    }
 97	
 98	    private void validateItems(CheckoutRequestDto request) {
 99	        if (request.getItems() == null || request.getItems().isEmpty()) {
100	            throw new InvalidOrderException();
101	        }
102	
103	        Set<String> seenSkus = new HashSet<>();
104	        for (var item : request.getItems()) {
105	            if (item.getSku() == null || item.getQuantity() == null || item.getQuantity() <= 0) {
106	                throw new InvalidOrderException();
107	            }
108	            if (!seenSkus.add(item.getSku())) {
109	                throw new InvalidOrderException();
110	            }
111	        }
112	
113	        for (var item : request.getItems()) {
114	            Product product = productService.getProduct(item.getSku());
115	            if (product == null) {
116	                throw new UnknownProductException();
117	            }
118	            if (product.isDiscontinued()) {
119	                throw new ProductDiscontinuedException();
120	            }
121	            if (product.getStock() < item.getQuantity()) {
122	                throw new InsufficientStockException();
123	            }
124	        }
125	    }
126	
127	    private void validateCustomer(CheckoutRequestDto request) {
128	        if (request.getCustomer() == null ||
129	                request.getCustomer().getCpf() == null ||
130	                request.getCustomer().getEmail() == null) {
131	            throw new InvalidOrderException();
132	        }
133	    }
134	
135	    private void validateRegion(CheckoutRequestDto request) {
136	        try {
137	            Region.valueOf(request.getRegion());
138	        } catch (IllegalArgumentException e) {
139	            throw new InvalidRegionException();
140	        }
141	    }
142	
143	    private void validateZipCode(CheckoutRequestDto request) {
144	        if (request.getZipCode() == null || !request.getZipCode().matches("\\d{8}")) {
145	            throw new InvalidZipCodeException();
146	        }
147	    }
148	
149	    private void validateShippingMethod(CheckoutRequestDto request) {
150	        ShippingMethod method;
151	        try {
152	            method = ShippingMethod.valueOf(request.getShippingMethod());
153	        } catch (IllegalArgumentException e) {
154	            throw new InvalidShippingMethodException();
155	        }
156	
157	        if (method == ShippingMethod.COURIER) {
158	            BigDecimal totalWeight = calculateTotalWeight(request);
159	            if (totalWeight.compareTo(new BigDecimal("5")) > 0) {
160	                throw new ShippingMethodUnavailableException();
161	            }
162	        }
163	    }
164	
165	    private void validateClubTier(CheckoutRequestDto request) {
166	        try {
167	            ClubTier.valueOf(request.getClubTier());
168	        } catch (IllegalArgumentException e) {
169	            throw new InvalidClubTierException();
170	        }
171	    }
172	
173	    private void validateCoupon(CheckoutRequestDto request) {
174	        if (request.getCoupon() != null && !request.getCoupon().isEmpty()) {
175	            try {
176	                CouponCode.valueOf(request.getCoupon());
177	            } catch (IllegalArgumentException e) {
178	                throw new InvalidCouponException();
179	            }
180	        }
181	    }
182	
183	    private void validatePaymentMethod(CheckoutRequestDto request) {
184	        PaymentMethod method;
185	        try {
186	            method = PaymentMethod.valueOf(request.getPaymentMethod());
187	        } catch (IllegalArgumentException e) {
188	            throw new InvalidPaymentMethodException();
189	        }
190	
191	        Integer installments = request.getInstallments() != null ? request.getInstallments() : 1;
192	
193	        if (method == PaymentMethod.PIX || method == PaymentMethod.BANK_SLIP) {
194	            if (installments != 1) {
195	                throw new InvalidInstallmentsException();
196	            }
197	        } else if (method == PaymentMethod.CREDIT_CARD) {
198	            if (installments < 1 || installments > 12) {
199	                throw new InvalidInstallmentsException();
200	            }
201	        }
202	    }
203	
204	    private BigDecimal calculateTotalWeight(CheckoutRequestDto request) {
205	        BigDecimal totalWeight = BigDecimal.ZERO;
206	        for (var item : request.getItems()) {
207	            Product product = productService.getProduct(item.getSku());
208	            BigDecimal itemWeight = product.getWeightKg().multiply(new BigDecimal(item.getQuantity()));
209	            totalWeight = totalWeight.add(itemWeight);
210	        }
211	        return totalWeight;
212	    }
213	}
