   134	import java.math.BigDecimal;
   135	import java.util.LinkedHashMap;
   136	import java.util.Map;
   137	
   138	@Converter(autoApply = true)
   139	public class OrderSummaryConverter implements AttributeConverter<OrderSummary, String> {
   140	
   141	    private static final ObjectMapper mapper = new ObjectMapper();
   142	
   143	    @Override
   144	    public String convertToDatabaseColumn(OrderSummary attribute) {
   145	        if (attribute == null) {
   146	            return null;
   147	        }
   148	        try {
   149	            Map<String, Object> map = new LinkedHashMap<>();
   150	            map.put("productsSubtotal", attribute.getProductsSubtotal());
   151	            map.put("couponDiscount", attribute.getCouponDiscount());
   152	            map.put("shippingCost", attribute.getShippingCost());
   153	            map.put("deliveryDays", attribute.getDeliveryDays());
   154	            map.put("insurance", attribute.getInsurance());
   155	            map.put("paymentAdjustment", attribute.getPaymentAdjustment());
   156	            map.put("finalTotal", attribute.getFinalTotal());
   157	            map.put("installments", attribute.getInstallments());
   158	            map.put("installmentAmount", attribute.getInstallmentAmount());
   159	            map.put("nextPurchaseCredit", attribute.getNextPurchaseCredit());
   160	            map.put("gift", attribute.getGift());
   161	            return mapper.writeValueAsString(map);
   162	        } catch (JsonProcessingException e) {
   163	            throw new RuntimeException(e);
   164	        }
   165	    }
   166	
   167	    @Override
   168	    public OrderSummary convertToEntityAttribute(String dbData) {
   169	        if (dbData == null) {
   170	            return null;
   171	        }
   172	        try {
   173	            @SuppressWarnings("unchecked")
   174	            Map<String, Object> map = mapper.readValue(dbData, Map.class);
   175	            return new OrderSummary(
   176	                    new BigDecimal(map.get("productsSubtotal").toString()),
   177	                    new BigDecimal(map.get("couponDiscount").toString()),
   178	                    new BigDecimal(map.get("shippingCost").toString()),
   179	                    ((Number) map.get("deliveryDays")).intValue(),
   180	                    new BigDecimal(map.get("insurance").toString()),
   181	                    new BigDecimal(map.get("paymentAdjustment").toString()),
   182	                    new BigDecimal(map.get("finalTotal").toString()),
   183	                    ((Number) map.get("installments")).intValue(),
   184	                    new BigDecimal(map.get("installmentAmount").toString()),
   185	                    new BigDecimal(map.get("nextPurchaseCredit").toString()),
   186	                    (Boolean) map.get("gift")
   187	            );
   188	        } catch (JsonProcessingException e) {
   189	            throw new RuntimeException(e);
   190	        }
   191	    }
   192	}
