   150	            map.put("productsSubtotal", attribute.getProductsSubtotal());
   151	            map.put("couponDiscount", attribute.getCouponDiscount());
   152	            map.put("shippingCost", attribute.getShippingCost());
   153	            map.put("deliveryDays", attribute.getDeliveryDays());
   154	            map.put("insurance", attribute.getInsurance());
   155	            map.put("paymentAdjustment", attribute.getPaymentAdjustment());
   156	            map.put("finalTotal", attribute.getFinalTotal());
   157	            map.put("installments", attribute.getInstallments());
   158	            map.put("installmentAmount", attribute.getInstallmentAmount());
   159	            map.put("nextPurchaseCredit", attribute.getNextPurchaseCredit());
   160	            map.put("gift", attribute.getGift());
   161	            return mapper.writeValueAsString(map);
